function leaf(v: ReadSpan<f64>): f64 {
  return v[0];
}
function forward(v: ReadSpan<f64>): f64 {
  leaf(v);
  return leaf(v);
}
export function entry(): f64 {
  const a: f64[] = [1.0];
  const v: ReadSpan<f64> = readSpan(a, 0, 1);
  return forward(v);
}

