export function copy(left: f64[], i: u32, right: f64[], value: f64): f64 {
  left[i] = value;
  return right[i];
}
export function entry(i: u32, value: f64): f64 {
  const a: f64[] = [1.0, 2.0];
  const alias = a;
  const b: f64[] = [1.0, 2.0];
  copy(alias, i, a, value);
  copy(a, i, b, value);
  return b[i];
}

