function leaf(a: f64[], n: u32, value: f64): f64 {
  return value;
}
function bridge(a: f64[], n: u32, value: f64): f64 {
  return leaf(a, n, value);
}
export function entry(n: u32, value: f64): f64 {
  const actual: f64[] = [1.0, 2.0];
  actual[2] = value;
  bridge(actual, n, value);
  bridge(actual, n, value);
  return actual[0];
}

